// Institutional Quant AI Report & Portfolio Allocator
const data = $input.first().json;
const signals = data.signals || [];
const market = data.market_summary || {};
const allocations = data.portfolio_allocation || {};
const topPick = data.top_pick || {};
const isHighConviction = data.is_high_conviction_alert || false;
const dateStr = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

const companyNames = {
  'AAPL': 'Apple Inc.', 'NVDA': 'NVIDIA Corporation', 'TSLA': 'Tesla, Inc.',
  'MSFT': 'Microsoft Corporation', 'AMZN': 'Amazon.com, Inc.',
  'GOOGL': 'Alphabet Inc. (Google)', 'META': 'Meta Platforms, Inc.', 'INTC': 'Intel Corporation'
};

const trendArrow = (t) => t === 'IMPROVING' ? '\u2191' : (t === 'DECLINING' ? '\u2193' : '\u2192');

let direction = 'NEUTRAL';
if (market.bullish_count > market.bearish_count) direction = 'BULLISH';
else if (market.bearish_count > market.bullish_count) direction = 'BEARISH';

const topPickName = companyNames[topPick.ticker] || topPick.ticker || 'N/A';

// Rank by conviction (confidence x |score-0.5|) instead of relying on scrape order
const ranked = [...signals].sort((a, b) => {
  const convA = (a.confidence || 0) * Math.abs((a.avg_sentiment || 0.5) - 0.5);
  const convB = (b.confidence || 0) * Math.abs((b.avg_sentiment || 0.5) - 0.5);
  return convB - convA;
});
const top3 = ranked.slice(0, 3);

let slackMsg = `*INSTITUTIONAL QUANT SENTIMENT REPORT | ${dateStr}*\n\n*Market Overview:*\n\u2022 *Regime:* \`${market.market_regime || 'BALANCED'}\`\n\u2022 *Risk Level:* \`${market.risk_assessment || 'MODERATE'}\`${(market.risk_assessment || '').toUpperCase() === 'HIGH' ? ' :warning:' : ''}\n\u2022 *Overall Sentiment Score:* \`${market.overall_sentiment} / 1.0\`\n\u2022 *Summary:* *${market.bullish_count}* Bullish  |  *${market.bearish_count}* Bearish  |  *${market.neutral_count}* Neutral\n\n*TOP PICK OF THE DAY:*\n\u2022 *${topPickName} (${topPick.ticker})* -> Signal: *${topPick.signal}* | AI Certainty: *${topPick.confidence_pct}%* | Score: *${topPick.score}*\n\n*\u2500\u2500\u2500\u2500\u2500 TOP 3 HIGH-CONVICTION MOVERS \u2500\u2500\u2500\u2500\u2500*\n`;

top3.forEach((s, i) => {
  const fullName = companyNames[s.ticker] || s.ticker;
  slackMsg += `${i + 1}. *${fullName} (${s.ticker})* ${trendArrow(s.trend)} \u2014 *${s.signal}* | Conf: *${(s.confidence * 100).toFixed(0)}%*\n`;
});

slackMsg += `\n*\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 FULL PORTFOLIO & TICKER BREAKDOWN \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500*\n`;

signals.forEach(s => {
  const fullName = companyNames[s.ticker] || s.ticker;
  let tag = 'HOLD';
  if (s.signal === 'STRONG_BUY') tag = 'STRONG BUY';
  else if (s.signal === 'BUY') tag = 'BUY';
  else if (s.signal === 'STRONG_SELL') tag = 'STRONG SELL';
  else if (s.signal === 'SELL') tag = 'SELL';

  const weight = allocations[s.ticker] || '0%';
  const pct = s.predicted_change_pct >= 0 ? `+${s.predicted_change_pct}%` : `${s.predicted_change_pct}%`;
  slackMsg += `\n*${fullName} (${s.ticker})* ${trendArrow(s.trend)}\n\u00bb *Signal:* ${tag} | *24h Est:* \`${pct}\` | *Weight:* \`${weight}\` | *Confidence:* \`${(s.confidence * 100).toFixed(0)}%\` (${s.num_articles} articles)\n`;
});

slackMsg += `\n*Quant Strategy Tip:* _Portfolio Weight % recommends Kelly-criterion allocation based on AI sentiment confidence._\n_FinBERT Pipeline \u2022 Processed ${data.articles_scraped} news in ${data.pipeline_execution_time_sec}s_`;

let urgentMsg = `*URGENT HIGH-CONVICTION TRADING ALERT | ${dateStr}*\nTop Opportunity Detected: *${topPickName} (${topPick.ticker})*\nSignal: *${topPick.signal}* | AI Confidence: *${topPick.confidence_pct}%*\nRecommended Action: Immediate review of long/short position.`;

return [{
  json: {
    slack_message: slackMsg,
    urgent_message: urgentMsg,
    is_high_conviction: isHighConviction,
    market_direction: direction,
    overall_sentiment: market.overall_sentiment,
    top_pick_ticker: topPick.ticker,
    top_pick_signal: topPick.signal,
    top3_tickers: top3.map(s => s.ticker)
  }
}];

const report = $('Step 3: Process & Compute Quant Metrics').first().json;
const subscribers = $input.first().json.subscribers || [];
const subscriber_emails = [...new Set(subscribers.map(({ email }) => email).filter(Boolean))];
return [{ json: { ...report, subscriber_emails, subscriber_count: subscriber_emails.length } }];
